#include <bits/stdc++.h>
using namespace std;
class Solution {
    vector<int>a;
    long long solve(int l,int r){
        if(r-l<=1)return 0;
        int m=(l+r)/2;long long ans=solve(l,m)+solve(m,r);
        vector<pair<int,int>> left,right;
        set<int>seen;
        for(int i=m-1;i>=l;i--){
            auto it=seen.upper_bound(a[i]);int bound=it==seen.end()?INT_MAX:*it;
            left.push_back({a[i],bound});seen.insert(a[i]);
        }
        seen.clear();
        for(int j=m;j<r;j++){
            auto it=seen.lower_bound(a[j]);int bound=it==seen.begin()?INT_MIN:*prev(it);
            right.push_back({a[j],bound});seen.insert(a[j]);
        }
        sort(left.begin(),left.end(),[](pair<int,int>x,pair<int,int>y){return x.second<y.second;});
        sort(right.begin(),right.end());
        vector<int>vals;for(auto &p:left)vals.push_back(p.first);
        sort(vals.begin(),vals.end());vals.erase(unique(vals.begin(),vals.end()),vals.end());
        vector<int>bit(vals.size()+1);auto add=[&](int i){for(;i<(int)bit.size();i+=i&-i)bit[i]++;};
        auto sum=[&](int i){int z=0;for(;i;i-=i&-i)z+=bit[i];return z;};
        int ptr=0,total=0;
        for(auto &p:right){
            while(ptr<(int)left.size()&&left[ptr].second>=p.first){
                // Bounds sorted ascending: handled by descending sweep below.
                break;
            }
        }
        sort(left.begin(),left.end(),[](pair<int,int>x,pair<int,int>y){return x.second>y.second;});
        sort(right.begin(),right.end(),[](pair<int,int>x,pair<int,int>y){return x.first>y.first;});
        ptr=0;
        for(auto &p:right){
            while(ptr<(int)left.size()&&left[ptr].second>=p.first){
                int id=lower_bound(vals.begin(),vals.end(),left[ptr].first)-vals.begin()+1;
                add(id);ptr++;total++;
            }
            int low=lower_bound(vals.begin(),vals.end(),p.second)-vals.begin();
            int high=lower_bound(vals.begin(),vals.end(),p.first)-vals.begin();
            ans+=sum(high)-sum(low);
        }
        return ans;
    }
public:
    int shadowPairs(vector<int>& nums){a=nums;return (int)solve(0,a.size());}
};
